(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.25)*18+Math.cos(y*0.013-t*0.18)*12+Math.sin((x+y)*0.009+t*0.4)*8;
  const w1y = Math.cos(y*0.02-t*0.22)*18+Math.sin(x*0.016+t*0.3)*12+Math.cos((x-y)*0.011-t*0.35)*8;
  const w2x = Math.sin(w1x*0.03+t*0.5)*6+Math.cos(w1y*0.025-t*0.4)*5;
  const w2y = Math.cos(w1y*0.03-t*0.45)*6+Math.sin(w1x*0.02+t*0.55)*5;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.5)*110, 70+Math.cos(t*0.35)*55, 0.07, 2.2, 1.0],
    [320+Math.cos(t*0.45)*100, 170+Math.sin(t*0.6)*50, 0.09, 1.8, 0.9],
    [240+Math.sin(t*0.28+2)*150, 120+Math.cos(t*0.42+1)*95, 0.055, 2.5, 1.1],
    [100+Math.cos(t*0.7+1)*85, 190+Math.sin(t*0.55+3)*65, 0.11, 1.6, 0.85],
    [380+Math.sin(t*0.38+4)*95, 50+Math.cos(t*0.8+2)*75, 0.065, 2.8, 1.05],
    [240+Math.cos(t*0.32+5)*130, 210+Math.sin(t*0.48)*85, 0.08, 2.0, 0.95],
    [60+Math.sin(t*0.62+3)*70, 100+Math.cos(t*0.52+4)*60, 0.1, 1.9, 0.8],
    [420+Math.cos(t*0.33+1)*80, 140+Math.sin(t*0.58+2)*70, 0.075, 2.4, 1.0]
  ];
  let aS=0, iS=0, wS=0;
  for(const[sX,sY,f,sp,w]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const wave=Math.sin(d*f-t*sp);
    const harm=Math.sin(d*f*1.618-t*sp*0.618+2.1)*0.5;
    aS+=wave*w; iS+=(Math.sin(d*f*0.7+t*sp*0.55+1.5)+harm)*w; wS+=Math.sin(d*f*0.5+t*sp*0.3-0.8)*w*0.4;
  }
  const n=8; const act=aS/n, inh=iS/n, warp=wS/n;
  const fbm=(ox,oy,oct)=>{
    let v=0,a=1,f=1;
    for(let i=0;i<oct;i++){v+=Math.sin(ox*f+oy*f*0.7+t*0.6+i*1.3)*a;a*=0.5;f*=2.1;}
    return v;
  };
  const bg=fbm(sx*0.035,sy*0.025,4)*0.5+fbm(sx*0.02+3,sy*0.03+7,3)*0.3;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const sp1=Math.sin(dist*0.045-ang*3.5-t*1.3), sp2=Math.sin(dist*0.035+ang*4.5-t*1.0);
  const sp3=Math.sin(dist*0.06-ang*2-t*2.0)*0.3;
  const spiral=(sp1+sp2+sp3)*0.35;
  const turbulence=Math.sin(sx*0.08+sy*0.06+t)*Math.cos(sx*0.06-sy*0.09+t*1.3)*0.25;
  const feed=act*0.6-inh*0.45+bg*0.35+spiral*0.3+warp*0.2+turbulence;
  const diff=Math.tanh(feed*2.0);
  const cellA=Math.tanh((Math.sin(sx*0.18)*Math.sin(sy*0.18)+Math.sin((sx+sy)*0.12+t)*0.4)*1.8)*0.25;
  const cellB=Math.tanh((Math.cos(sx*0.14-sy*0.1+t*0.7)*Math.sin(sx*0.08+sy*0.16-t*0.5))*1.5)*0.15;
  const blend=diff*0.65+cellA*0.2+cellB*0.15, v=blend*0.5+0.5;
  const pal=[
    [6,12,52],[12,45,95],[18,90,120],[25,140,135],[45,175,130],
    [120,195,100],[200,190,70],[220,155,55],[210,110,60],[185,70,65],
    [140,40,75],[85,22,60],[40,14,48],[6,12,52]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const r0=pal[i][0]+(pal[i+1][0]-pal[i][0])*f, g0=pal[i][1]+(pal[i+1][1]-pal[i][1])*f, b0=pal[i][2]+(pal[i+1][2]-pal[i][2])*f;
  const lum=0.82+Math.sin(diff*Math.PI)*0.18;
  const edge=Math.abs(diff)>0.65?1.2:Math.abs(diff)>0.4?1.08:1.0;
  const glow=Math.max(0,Math.abs(diff)-0.5)*0.4;
  const gc=[255,240,200];
  return[
    Math.min(255,((r0*(1-glow)+gc[0]*glow)*lum*edge))|0,
    Math.min(255,((g0*(1-glow)+gc[1]*glow)*lum*edge))|0,
    Math.min(255,((b0*(1-glow)+gc[2]*glow)*lum*edge))|0
  ];
}
